from pathlib import Path
import json,numpy as np,pandas as pd,anndata as ad,hashlib
from scipy import sparse
from sklearn.metrics import adjusted_rand_score
import scanpy as sc
R=Path(__file__).resolve().parent;checks=[]
def check(name,passed):
 checks.append({'check':name,'passed':bool(passed)});assert passed,name
obs=pd.read_csv(R/'cell_annotations.csv.gz',index_col=0,dtype={'cluster':str,'cluster_seed2':str});source=pd.read_csv(R/'source_inputs/all_cell_metadata_before_QC.csv.gz',index_col=0);expected=source.index[source.tissue.eq('HCC_tumor')&source.passes_QC];check('exact_HCC_QC_cell_set_and_order',obs.index.equals(expected));summary=json.loads((R/'clustering_summary.json').read_text());check('independent_seed_ARI',np.isclose(adjusted_rand_score(obs.cluster,obs.cluster_seed2),summary['seed_stability_ARI']));u=pd.read_csv(R/'UMAP_coordinates.csv.gz',index_col=0);check('both_UMAP_finite_and_exact_cell_order',u.index.equals(obs.index) and np.isfinite(u.to_numpy()).all());graph=sparse.load_npz(R/'neighbor_graph.npz');check('neighbor_graph_nonempty_per_cell',graph.shape==(len(obs),len(obs)) and np.all(graph.getnnz(axis=1)>0));recon=ad.AnnData(sparse.csr_matrix((len(obs),1)));sc.tl.leiden(recon,adjacency=graph,resolution=.8,random_state=202642,flavor='igraph',n_iterations=2,directed=False);check('saved_graph_reconstructs_published_Leiden',np.isclose(adjusted_rand_score(obs.cluster,recon.obs.leiden),1));d=pd.read_csv(R/'cluster_annotations.csv');check('21_cluster_labels_complete',len(d)==21 and d.cells.sum()==len(obs) and set(d.cluster.astype(str))==set(obs.cluster));mk=pd.read_csv(R/'cluster_top40_markers.csv.gz');check('top_marker_statistics_finite',np.isfinite(mk[['scores','pvals','pvals_adj','logfoldchanges']].to_numpy()).all());check('top_markers_all_21_groups',mk.group.nunique()==21 and len(mk)==840)
full=ad.read_h5ad(R/'HCC_raw_counts_QC.h5ad',backed='r');tot=[];unique_detected=[]
for start in range(0,len(obs),2000):
 block=full.X[start:start+2000];tot.extend(np.asarray(block.sum(1)).ravel());unique_detected.extend(np.asarray((block>0).sum(1)).ravel())
check('full_raw_matrix_totals_against_source',np.array_equal(tot,source.loc[obs.index,'total_counts']));pg=np.asarray(full[:,['PGAM5']].X.toarray()).ravel();check('raw_PGAM5_against_source',np.array_equal(pg,source.loc[obs.index,'PGAM5_counts']));full.file.close();small=ad.read_h5ad(R/'HCC_annotation_marker_subset.h5ad');check('portable_h5ad_annotation_order_and_shape',small.obs_names.equals(obs.index) and small.shape==(56719,110));check('portable_gene_subset_counts_match',np.array_equal(small.layers['counts'][:,small.var_names.get_loc('PGAM5')].toarray().ravel(),pg));check('portable_full_library_normalization',np.allclose(small.X[:,small.var_names.get_loc('PGAM5')].toarray().ravel(),np.log1p(pg/obs.total_counts.to_numpy()*10000)))
for f,h in json.loads((R/'source_input_hashes.json').read_text()).items():check('source_hash_'+f,hashlib.sha256((R/'source_inputs'/f).read_bytes()).hexdigest()==h)
pd.DataFrame(checks).to_csv(R/'independent_audit_checks.csv',index=False);(R/'audit_summary.json').write_text(json.dumps({'checks_passed':len(checks),'minimum_detected_unique_gene_symbols':int(min(unique_detected)),'QC_detection_grain':'Original 36601 feature rows before duplicate-symbol collapse; original QC records used'},indent=2));print('Passed',len(checks),'checks',flush=True)
